// Virtual Address (VA) seen by the program
int data_item = 42;
int* va_ptr = &data_item;

// The value of va_ptr is the VA (e.g., 0x7FF...)
// This address is local to the current process address space.

// Hardware (MMU) handles translation:
// 1. Split VA into Page Number and Offset
// 2. Lookup Page Table Entry (PTE)
// 3. PTE provides the Physical Frame Number (PFN)
// 4. PFN + Offset = Physical Address (PA)

char value = *((char*)va_ptr); // Access requires VA -> PA translation

// Isolation: VA_P1 == VA_P2 maps to PA_X != PA_Y
// Shared memory involves mapping the same PA to different VAs.
